// Node 4: Calculate All 8 Daily Gym KPIs & Generate Executive HTML Email Report
const members = $('2. Read Members (Google Sheets)').all().map(i => i.json);
const payments = $('3. Read Payments (Google Sheets)').all().map(i => i.json);

const todayIST = new Intl.DateTimeFormat('en-CA', {
  timeZone: 'Asia/Kolkata',
  year: 'numeric',
  month: '2-digit',
  day: '2-digit'
}).format(new Date());
const [y1, m1, d1] = todayIST.split('-').map(Number);
const utcToday = Date.UTC(y1, m1 - 1, d1);

let totalRegistered = members.length;
let currentlyActive = 0;
let expiredMemberships = 0;
let expiringToday = 0;
let expiringIn3Days = 0;
let pendingPayments = 0;

for (const m of members) {
  if (m.Payment_Status === 'Pending') pendingPayments++;
  if (!m.Expiry_Date) continue;
  const [y2, m2, d2] = m.Expiry_Date.split('-').map(Number);
  const diff = Math.round((Date.UTC(y2, m2 - 1, d2) - utcToday) / (1000 * 60 * 60 * 24));
  if (diff >= 0) currentlyActive++;
  else expiredMemberships++;
  if (diff === 0) expiringToday++;
  if (diff === 3) expiringIn3Days++;
}

const todayPaidPayments = payments.filter(p => p.Payment_Date === todayIST && p.Payment_Status === 'Paid');
const paymentsReceivedToday = todayPaidPayments.length;
const totalRevenueToday = todayPaidPayments.reduce((acc, p) => acc + Number(p.Amount || 0), 0);

const htmlReport = `<h2>Daily Gym Summary (${todayIST})</h2>
<ul>
  <li><strong>Total Registered Members:</strong> ${totalRegistered}</li>
  <li><strong>Currently Active Members:</strong> ${currentlyActive}</li>
  <li><strong>Expired Memberships:</strong> ${expiredMemberships}</li>
  <li><strong>Memberships Expiring Today:</strong> ${expiringToday}</li>
  <li><strong>Memberships Expiring in 3 Days:</strong> ${expiringIn3Days}</li>
  <li><strong>Pending Payments:</strong> ${pendingPayments}</li>
  <li><strong>Payments Received Today:</strong> ${paymentsReceivedToday}</li>
  <li><strong>Total Revenue Collected Today:</strong> ₹${totalRevenueToday.toLocaleString('en-IN')}</li>
</ul>`;

return [{
  json: {
    todayIST,
    totalRegistered,
    currentlyActive,
    expiredMemberships,
    expiringToday,
    expiringIn3Days,
    pendingPayments,
    paymentsReceivedToday,
    totalRevenueToday,
    htmlReport
  }
}];
